"use client";

import React, { useRef, useState } from "react";
import { useFrame } from "@react-three/fiber";
import { RoundedBox, Text, Float } from "@react-three/drei";
import * as THREE from "three";

interface ARCardProps {
  /** Card title */
  title: string;
  /** Card description */
  description?: string;
  /** Card position in 3D space [x, y, z] */
  position?: [number, number, number];
  /** Card rotation [x, y, z] in radians */
  rotation?: [number, number, number];
  /** Card width (default: 2) */
  width?: number;
  /** Card height (default: 1.2) */
  height?: number;
  /** Card depth (default: 0.05) */
  depth?: number;
  /** Accent color (default: "#A78BFA") */
  accentColor?: string;
  /** Enable floating animation (default: true) */
  floating?: boolean;
  /** Click handler */
  onClick?: () => void;
}

/**
 * AR Card
 *
 * 3D card component designed for spatial interfaces and AR experiences.
 * Features glass-morphic design, floating animation, and interactive
 * hover states with emissive glow. Place inside XRScene.
 */
export function ARCard({
  title,
  description,
  position = [0, 0, 0],
  rotation = [0, 0, 0],
  width = 2,
  height = 1.2,
  depth = 0.05,
  accentColor = "#A78BFA",
  floating = true,
  onClick,
}: ARCardProps) {
  const meshRef = useRef<THREE.Mesh>(null);
  const [hovered, setHovered] = useState(false);

  useFrame((state) => {
    if (!meshRef.current) return;
    const t = state.clock.elapsedTime;
    meshRef.current.scale.setScalar(1 + Math.sin(t * 1.5) * 0.005);

    const material = meshRef.current.material as THREE.MeshPhysicalMaterial;
    if (material.emissiveIntensity !== undefined) {
      material.emissiveIntensity = THREE.MathUtils.lerp(
        material.emissiveIntensity,
        hovered ? 0.3 : 0.05,
        0.1
      );
    }
  });

  const content = (
    <group position={position} rotation={rotation}>
      {/* Card body — glass morphic */}
      <RoundedBox
        ref={meshRef}
        args={[width, height, depth]}
        radius={0.06}
        smoothness={4}
        onPointerOver={() => setHovered(true)}
        onPointerOut={() => setHovered(false)}
        onClick={onClick}
      >
        <meshPhysicalMaterial
          color="#111115"
          metalness={0.1}
          roughness={0.2}
          transmission={0.4}
          thickness={0.5}
          ior={1.5}
          transparent
          opacity={0.85}
          emissive={new THREE.Color(accentColor)}
          emissiveIntensity={0.05}
        />
      </RoundedBox>

      {/* Accent border glow */}
      <RoundedBox
        args={[width + 0.02, height + 0.02, depth * 0.5]}
        radius={0.07}
        smoothness={4}
        position={[0, 0, -depth * 0.3]}
      >
        <meshBasicMaterial
          color={accentColor}
          transparent
          opacity={hovered ? 0.15 : 0.05}
        />
      </RoundedBox>

      {/* Title text — uses default drei font (no custom font file needed) */}
      <Text
        position={[0, description ? 0.2 : 0, depth * 0.6]}
        fontSize={0.15}
        maxWidth={width * 0.85}
        textAlign="center"
        color="#fafafa"
        anchorX="center"
        anchorY="middle"
      >
        {title}
      </Text>

      {/* Description text */}
      {description && (
        <Text
          position={[0, -0.15, depth * 0.6]}
          fontSize={0.08}
          maxWidth={width * 0.8}
          textAlign="center"
          color="#a1a1aa"
          anchorX="center"
          anchorY="middle"
        >
          {description}
        </Text>
      )}

      {/* Accent line at bottom */}
      <mesh position={[0, -height / 2 + 0.04, depth * 0.6]}>
        <planeGeometry args={[width * 0.6, 0.003]} />
        <meshBasicMaterial color={accentColor} transparent opacity={0.6} />
      </mesh>
    </group>
  );

  if (floating) {
    return (
      <Float speed={2} rotationIntensity={0.1} floatIntensity={0.3}>
        {content}
      </Float>
    );
  }

  return content;
}

"use client";

import React, { Suspense, useRef, useState, useCallback } from "react";
import { Canvas } from "@react-three/fiber";
import { OrbitControls, Environment, Float } from "@react-three/drei";
import { cn } from "@/lib/utils";

interface XRSceneProps {
  /** Children (3D objects) */
  children: React.ReactNode;
  /** Enable AR mode button (default: false) */
  enableAR?: boolean;
  /** Enable orbit controls (default: true) */
  enableOrbitControls?: boolean;
  /** Background color (default: transparent) */
  backgroundColor?: string;
  /** Camera position [x, y, z] */
  cameraPosition?: [number, number, number];
  /** Environment preset */
  environment?: "sunset" | "dawn" | "night" | "warehouse" | "forest" | "apartment" | "studio" | "city" | "park" | "lobby";
  /** Additional CSS classes */
  className?: string;
  /** Canvas height */
  height?: string | number;
  /** Fallback when WebXR unavailable */
  fallback?: React.ReactNode;
}

/**
 * XR Scene
 *
 * Base scene wrapper for 3D/AR components using React Three Fiber.
 * Provides camera controls, environment lighting, and optional
 * WebXR AR session support.
 *
 * @example
 * ```tsx
 * <XRScene enableAR cameraPosition={[0, 1, 3]}>
 *   <ARCard position={[0, 1, 0]} />
 * </XRScene>
 * ```
 */
export function XRScene({
  children,
  enableAR = false,
  enableOrbitControls = true,
  backgroundColor = "transparent",
  cameraPosition = [0, 1.5, 3],
  environment = "studio",
  className,
  height = 500,
  fallback,
}: XRSceneProps) {
  const [arSupported, setArSupported] = useState<boolean | null>(null);
  const [arActive, setArActive] = useState(false);

  // Check AR support
  const checkAR = useCallback(async () => {
    if (typeof navigator === "undefined" || !("xr" in navigator)) {
      setArSupported(false);
      return;
    }
    try {
      const supported = await (navigator as Navigator & { xr: { isSessionSupported: (mode: string) => Promise<boolean> } }).xr.isSessionSupported("immersive-ar");
      setArSupported(supported);
    } catch {
      setArSupported(false);
    }
  }, []);

  React.useEffect(() => {
    if (enableAR) checkAR();
  }, [enableAR, checkAR]);

  return (
    <div
      className={cn("relative overflow-hidden rounded-xl", className)}
      style={{
        height: typeof height === "number" ? `${height}px` : height,
        background: backgroundColor === "transparent" ? "#09090b" : backgroundColor,
      }}
    >
      <Canvas
        camera={{ position: cameraPosition, fov: 50 }}
        style={{ background: backgroundColor }}
        gl={{ antialias: true, alpha: true }}
      >
        <Suspense fallback={null}>
          <ambientLight intensity={0.4} />
          <directionalLight position={[5, 5, 5]} intensity={0.8} />
          <Environment preset={environment} />
          {enableOrbitControls && !arActive && (
            <OrbitControls
              enablePan={false}
              enableZoom={true}
              minDistance={1}
              maxDistance={10}
              autoRotate
              autoRotateSpeed={0.5}
            />
          )}
          {children}
        </Suspense>
      </Canvas>

      {/* AR button overlay */}
      {enableAR && arSupported && (
        <button
          onClick={() => setArActive(!arActive)}
          className="absolute bottom-4 right-4 rounded-lg px-4 py-2 text-xs font-bold transition-all duration-200 hover:brightness-110"
          style={{
            background: arActive ? "#34D399" : "#A78BFA",
            color: "#09090b",
            boxShadow: arActive
              ? "0 0 20px rgba(52,211,153,0.3)"
              : "0 0 20px rgba(167,139,250,0.3)",
          }}
        >
          {arActive ? "Exit AR" : "Enter AR"}
        </button>
      )}

      {enableAR && arSupported === false && (
        <div className="absolute bottom-4 right-4 rounded-lg px-3 py-1.5 text-[10px] font-medium"
          style={{ background: "rgba(255,255,255,0.06)", color: "#52525b" }}>
          AR not supported on this device
        </div>
      )}
    </div>
  );
}
